// #d65b5b (6a993d6fbd1469e36cd65b5b) AC5 «המשך בפועל וסיבת הסיום … בדוח» — в шапке отчёта у менеджера «סיבת סיום» и «משך».
// Кейс END-001 (пять причин окончания — пять тестов). Роль — business testim (сессия bizt), десктоп. Только чтение, звонков нет.
// Источник истины — get_candidate_report (attempt.end_reason, attempt.duration_seconds): экран сверяется с API; ожидаемые коды причин
// и длительности из записанных звонков (21.10–17.11) проверяются как «данные не менялись». Кандидат ищется по точному имени.
import { test, expect } from '../../fixtures';
import { viewByName, openReportPage } from './report-view-helpers';
import { endReasonText, minSec } from '../admin-support/support-helpers';

const HASH = '#d65b5b · #6a993d6fbd1469e36cd65b5b';
const CASES = [
  { name: 'QA-C2-2110-D2', code: 'predefined_condition', text: 'התקיים תנאי סיום שהוגדר בתרחיש', duration: '2:17' },
  { name: 'QA-PHONE-17fdd9-2210', code: 'candidate_ended', text: 'המועמד סיים את השיחה', duration: '5:36' },
  { name: 'QA-C7-2110-D3', code: 'customer_refused', text: 'הלקוח המדומה סירב להמשיך', duration: '0:52' },
  { name: 'QA-C4-2110-D2', code: 'duration_elapsed', text: 'הזמן שהוקצב לשיחה הסתיים', duration: '5:15' },
  { name: 'QA-G4-A-1321', code: 'next_step_achieved', text: 'נקבע צעד הבא', duration: '2:53' },
] as const;

test.describe(`Отчёт у менеджера — «סיבת סיום» и «משך» в шапке (${HASH})`, () => {
  for (const c of CASES) {
    test(`${c.name}: «סיבת סיום» = «${c.text}», «משך» = ${c.duration} דק׳ (как в API) @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
      const page = await asUser('bizt');
      await page.setViewportSize({ width: 1440, height: 900 });
      const { id, view } = await viewByName(page, c.name);

      // Данные: код причины и длительность из записанного звонка.
      expect(view.attempt?.end_reason, `end_reason у ${c.name} в API — данные изменились`).toBe(c.code);
      const seconds = view.attempt?.duration_seconds ?? view.recording?.duration_seconds;
      expect(typeof seconds, `duration_seconds у ${c.name} в API`).toBe('number');
      expect(minSec(seconds as number), `длительность ${c.name} в API`).toBe(c.duration);
      expect(endReasonText(c.code)).toBe(c.text);

      const meta = await openReportPage(page, id);
      // Источник: AC5 + реджект 21.10 — причина окончания и фактическая длительность в шапке отчёта, значения как в API.
      await expect(meta.locator('[data-meta="end-reason"] dt')).toHaveText('סיבת סיום');
      await expect(meta.locator('[data-meta="end-reason"] dd')).toHaveText(endReasonText(view.attempt?.end_reason));
      await expect(meta.locator('[data-meta="duration"] dt')).toHaveText('משך');
      await expect(meta.locator('[data-meta="duration"] dd')).toHaveText(`${minSec(seconds as number)} דק׳`);
      // R5 (решение 17.11): причина показывается как причина, а не как слово о сбое.
      await expect(meta.locator('[data-meta="end-reason"] dd')).not.toContainText('כשל');
    });
  }
});
